document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".faq-item");e.forEach(t=>{t.querySelector(".faq-q").addEventListener("click",()=>{e.forEach(e=>{e!==t&&e.classList.remove("active")}),t.classList.toggle("active")})});const t=(e,t)=>{"undefined"!=typeof gtag&&gtag("event",e,{event_category:"conversion",event_label:t})};document.querySelectorAll('a[href^="https://wa.me"]').forEach(e=>{e.addEventListener("click",()=>t("click_whatsapp",e.textContent.trim()))}),document.querySelectorAll('a[href^="tel:"]').forEach(e=>{e.addEventListener("click",()=>t("click_call",e.textContent.trim()))})});